<script setup lang="ts">
import {getRequestError} from '~/utils/errors'
import type {AdminTeamResult} from '~/types/api'
definePageMeta({layout:'admin',middleware:'admin'})
useSeoMeta({title:'Admin team · BARNALI',robots:'noindex,nofollow'})
const api=useApi();const auth=useAuth();const {data,pending,error,refresh}=await useAsyncData('admin-team',()=>api.request<AdminTeamResult>('/admin/team'))
const email=ref('');const role=ref('MODERATOR');const inviteUrl=ref('');const busy=ref('');const message=ref('');const actionError=ref('')
const isOwner=computed(()=>auth.user.value?.role==='OWNER')
async function invite(){busy.value='invite';actionError.value='';message.value='';inviteUrl.value='';try{const result=await api.request<{inviteUrl:string}>('/admin/team/invitations',{method:'POST',body:{email:email.value,role:role.value}});inviteUrl.value=result.inviteUrl;email.value='';message.value='Invitation created. Copy the one-time link and deliver it through a trusted channel.';await refresh()}catch(e:unknown){actionError.value=getRequestError(e,'Invitation could not be created.')}finally{busy.value=''}}
async function copyLink(){try{await navigator.clipboard.writeText(inviteUrl.value);message.value='Invitation link copied. Share it only with the intended recipient.'}catch{actionError.value='Clipboard access was blocked. Select and copy the link manually.'}}
async function revoke(id:string){const reason=window.prompt('Enter a reason for revoking this administrator invitation:');if(!reason?.trim())return;busy.value=id;actionError.value='';try{await api.request(`/admin/team/invitations/${id}/revoke`,{method:'POST',body:{reason}});message.value='Invitation revoked.';inviteUrl.value='';await refresh()}catch(e:unknown){actionError.value=getRequestError(e,'Invitation could not be revoked.')}finally{busy.value=''}}
async function changeRole(member:AdminTeamResult['admins'][number]){const next=window.prompt(`Set role for ${member.displayName}. Enter SUPER_ADMIN, MODERATOR, ANALYTICS_VIEWER, or SUPPORT_ADMIN:`,member.role);if(!next)return;const reason=window.prompt('Enter a reason for the role change:');if(!reason?.trim())return;busy.value=member.userId;actionError.value='';try{await api.request(`/admin/team/${member.userId}/role`,{method:'PATCH',body:{role:next.toUpperCase(),reason}});message.value='Administrator role updated.';await refresh()}catch(e:unknown){actionError.value=getRequestError(e,'Role could not be changed.')}finally{busy.value=''}}
async function toggle(member:AdminTeamResult['admins'][number]){const reason=window.prompt(`${member.active?'Revoke':'Restore'} access for ${member.displayName}. Enter a reason:`);if(!reason?.trim())return;busy.value=member.userId;actionError.value='';try{await api.request(`/admin/team/${member.userId}/active`,{method:'PATCH',body:{active:!member.active,reason}});message.value='Administrator access updated.';await refresh()}catch(e:unknown){actionError.value=getRequestError(e,'Administrator access could not be updated.')}finally{busy.value=''}}
</script>
<template>
 <div class="admin-heading"><div><span class="eyebrow">Access control</span><h1>Admin team & permissions</h1><p>Delegate only the access each trusted team member needs.</p></div></div>
 <p v-if="message" class="notice notice--success" role="status">{{message}}</p><p v-if="actionError" class="notice notice--error" role="alert">{{actionError}}</p>
 <section v-if="isOwner" class="surface team-invite"><div><h2>Invite an administrator</h2><p class="muted">The recipient establishes their own credentials. The token is stored only as a hash and expires in 7 days. No email is sent from this environment.</p></div><form class="team-invite__form" @submit.prevent="invite"><div class="form-field"><label for="invite-email">Email address</label><input id="invite-email" v-model="email" class="input" type="email" maxlength="254" required></div><div class="form-field"><label for="invite-role">Role</label><select id="invite-role" v-model="role" class="select"><option value="MODERATOR">Moderator</option><option value="ANALYTICS_VIEWER">Analytics viewer</option><option value="SUPPORT_ADMIN">Support admin</option><option value="SUPER_ADMIN">Super admin</option></select></div><button class="btn" :disabled="busy==='invite'">{{busy==='invite'?'Creating…':'Create invitation'}}</button></form><div v-if="inviteUrl" class="invite-link"><label for="new-invite-link">One-time invitation link</label><input id="new-invite-link" class="input" readonly :value="inviteUrl"><button class="btn btn--outline btn--small" type="button" @click="copyLink">Copy link</button><p class="muted">Close or leave this page only after sharing. The token is shown once and cannot be recovered.</p></div></section>
 <h2 class="section-title">Administrators</h2><div v-if="pending&&!data" class="surface surface-pad" role="status">Loading admin team…</div><div v-else-if="error" class="notice notice--error" role="alert">{{getRequestError(error,'Admin team is unavailable.')}} <button class="btn btn--outline btn--small" @click="refresh()">Retry</button></div><EmptyState v-else-if="!data?.admins.length" title="No administrators found" description="The owner will appear here after the first successful bootstrap." />
 <div v-else class="surface table-wrap"><table class="data-table"><thead><tr><th>Administrator</th><th>Role</th><th>Status</th><th>Last used</th><th>Access</th></tr></thead><tbody><tr v-for="member in data.admins" :key="member.userId"><td><strong>{{member.displayName}}</strong><br>{{member.email}} · @{{member.username}}</td><td>{{member.role}}</td><td><span class="status-pill" :class="{'status-pill--danger':!member.active}">{{member.active?'Active':'Disabled'}}</span></td><td>{{member.lastUsedAt?new Date(member.lastUsedAt).toLocaleString():'No use recorded'}}</td><td><div v-if="isOwner&&member.role!=='OWNER'" class="admin-controls"><button class="btn btn--outline btn--small" :disabled="busy===member.userId" @click="changeRole(member)">Change role</button><button class="btn btn--outline btn--small" :disabled="busy===member.userId" @click="toggle(member)">{{member.active?'Revoke':'Restore'}}</button></div><span v-else class="muted">Owner protected</span></td></tr></tbody></table></div>
 <h2 class="section-title">Invitations</h2><EmptyState v-if="data&&!data.invitations.length" title="No invitations" description="Invitations will be listed here without their secret tokens."/><div v-else-if="data?.invitations.length" class="surface table-wrap"><table class="data-table"><thead><tr><th>Email</th><th>Role</th><th>Status</th><th>Created</th><th>Expires</th><th></th></tr></thead><tbody><tr v-for="invitation in data.invitations" :key="invitation.id"><td>{{invitation.email}}<br><span class="muted">Invited by {{invitation.inviterName}}</span></td><td>{{invitation.role}}</td><td>{{invitation.status}}</td><td>{{new Date(invitation.createdAt).toLocaleDateString()}}</td><td>{{new Date(invitation.expiresAt).toLocaleString()}}</td><td><button v-if="isOwner&&invitation.status==='PENDING'" class="btn btn--outline btn--small" :disabled="busy===invitation.id" @click="revoke(invitation.id)">Revoke</button></td></tr></tbody></table></div>
</template>
<style scoped>.team-invite{display:grid;gap:16px;padding:20px;margin-bottom:25px}.team-invite h2{margin:0;font:700 1.3rem var(--b-font-display)}.team-invite p{margin:5px 0}.team-invite__form{display:grid;grid-template-columns:minmax(180px,1fr) minmax(160px,.7fr) auto;align-items:end;gap:12px}.team-invite__form .btn{min-height:46px}.invite-link{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:end}.invite-link label,.invite-link p{grid-column:1/-1}.section-title{margin:26px 0 12px;font:700 1.3rem var(--b-font-display)}@media(max-width:650px){.team-invite__form{grid-template-columns:1fr}.invite-link{grid-template-columns:1fr}}</style>
